import {accountFetch} from "/static/assets/api.1e898baa005a.js";

export function initializeMembershipAdmin(){
 const trigger=document.createElement('button');trigger.type='button';trigger.id='membershipAdminOpen';trigger.className='topbar-action';trigger.textContent='管理后台';document.querySelector('.topbar-tools').append(trigger);
 const dialog=document.createElement('dialog');dialog.className='account-dialog membership-admin';dialog.id='membershipAdmin';dialog.setAttribute('aria-labelledby','membershipAdminTitle');
 dialog.innerHTML=`<div class="account-dialog-head"><div><p class="account-eyebrow">JT ADMIN</p><h2 id="membershipAdminTitle">用户与套餐管理</h2></div><button type="button" class="account-close" id="membershipAdminClose" aria-label="关闭管理后台">×</button></div>
 <p id="membershipAdminStatus" role="status" aria-live="polite"></p><nav class="admin-tabs" aria-label="管理功能"><button type="button" data-admin-tab="plans" aria-pressed="true">套餐设置</button><button type="button" data-admin-tab="codes" aria-pressed="false">登录激活码</button><button type="button" data-admin-tab="renewals" aria-pressed="false">续费码</button><button type="button" data-admin-tab="users" aria-pressed="false">用户</button><button type="button" data-admin-tab="reservations" aria-pressed="false">额度核对</button></nav>
 <section data-admin-panel="plans"><div class="admin-form-header"><label for="adminPlanSelect">选择套餐</label><select id="adminPlanSelect"><option value="">新建套餐</option></select></div><form id="adminPlanForm" class="admin-form"><input type="hidden" name="plan_id"><label>套餐名称<input name="name" maxlength="100" required placeholder="例如：创作月卡"></label><label>价格说明<input name="price_display" maxlength="100" placeholder="例如：99 元 / 月，线下支付"></label><label>有效天数<input name="duration_days" type="number" min="1" max="3660" value="30" required></label><label>并发任务数<input name="max_concurrent" type="number" min="1" max="20" value="1" required></label><label>图片额度<input name="image_units" type="number" min="0" max="1000000" value="100" required></label><label>视频额度<input name="video_units" type="number" min="0" max="1000000" value="10" required></label><fieldset><legend>开放功能</legend><label><input type="checkbox" name="feature" value="image" checked>图片生成</label><label><input type="checkbox" name="feature" value="video" checked>视频生成</label><label><input type="checkbox" name="feature" value="upload" checked>素材上传</label><label><input type="checkbox" name="feature" value="history" checked>历史记录</label><label><input type="checkbox" name="feature" value="favorites" checked>收藏</label></fieldset><fieldset><legend>生成方式</legend><label><input type="checkbox" name="backend" value="cloud" checked>云端</label><label><input type="checkbox" name="backend" value="api">API 生图</label><label><input type="checkbox" name="backend" value="local">本地</label></fieldset><label class="admin-checkbox"><input type="checkbox" name="active" checked>启用套餐</label><p class="account-help admin-full">调整套餐适用于之后生成的激活码，已发放权益按发码时的套餐执行。</p><button type="submit" class="account-primary admin-full">保存套餐</button></form></section>
 <section data-admin-panel="codes" hidden><p id="adminCodeHelp" class="account-help">每个登录激活码对应一个独立账号，首次使用时开通套餐，以后用同一个码继续登录。</p><form id="adminCodeForm" class="admin-form"><label class="admin-full">对应套餐<select id="adminCodePlan" name="plan_id" required></select></label><label>生成数量<input name="count" type="number" min="1" max="100" value="1" required></label><label>备注<input name="note" maxlength="500" placeholder="订单或用途备注"></label><button type="submit" class="account-primary admin-full">生成登录激活码</button></form><section id="adminIssued" class="admin-issued" hidden><label for="adminIssuedCodes">本次生成的登录激活码</label><p class="account-help">完整码仅显示这一次，请复制保存后再关闭。</p><textarea id="adminIssuedCodes" readonly rows="5" spellcheck="false" autocomplete="off"></textarea><button type="button" class="account-secondary" id="adminCopyCodes">复制全部</button></section><div class="admin-table-wrap"><table><thead><tr><th>激活码尾号</th><th>套餐 / 备注</th><th>状态</th><th>操作</th></tr></thead><tbody id="adminCodesRows"></tbody></table></div></section>
 <section data-admin-panel="users" hidden><p class="account-help">停用用户会立即使其会话失效。换码后旧登录码与会话失效，新码仍进入原账号，套餐、历史和收藏保留。</p><div class="admin-table-wrap"><table><thead><tr><th>用户</th><th>账号状态</th><th>操作</th></tr></thead><tbody id="adminUsersRows"></tbody></table></div></section>
 <section data-admin-panel="reservations" hidden><p class="account-help">先核对生成服务中的实际结果，再处理未结算额度。进行中、排队中或仍在恢复核对的任务不可操作。</p><button type="button" class="account-secondary" id="adminReservationsRefresh">刷新待核对列表</button><form id="adminSettleForm" class="admin-issued admin-form" hidden><h3 id="adminSettleTitle" class="admin-full"></h3><p id="adminSettleTarget" class="account-help admin-full"></p><label class="admin-full">核对依据（至少 10 字）<textarea id="adminSettleNote" name="note" minlength="10" maxlength="500" rows="3" required placeholder="填写核对时间、实际结果及处理依据"></textarea></label><div class="admin-settle-actions admin-full"><button type="submit" id="adminSettleSubmit" class="account-primary">确认处理</button><button type="button" id="adminSettleCancel" class="account-secondary">返回列表</button></div></form><div class="admin-table-wrap"><table><thead><tr><th>任务 / 用户</th><th>额度占用</th><th>任务状态 / 原因</th><th>处理</th></tr></thead><tbody id="adminReservationsRows"></tbody></table></div></section>`;
 document.body.append(dialog);
 const el=id=>dialog.querySelector('#'+id),status=el('membershipAdminStatus');let plans=[],tab='plans',busy=false,settlement=null;
 dialog.querySelector('.admin-tabs').after(el('adminIssued'));
 const offsets={codes:0,renewals:0,users:0},codeTab=()=>tab==='renewals'?'renewals':'codes',codePath=()=>tab==='renewals'?'codes':'access-codes',codeName=()=>tab==='renewals'?'续费码':'登录激活码';
 for(const kind of ['codes','users']){
  const nav=document.createElement('div');nav.className='admin-pagination';
  nav.innerHTML='<button type="button" class="account-secondary" data-prev>上一页</button><span></span><button type="button" class="account-secondary" data-next>下一页</button>';
  nav.dataset.pagination=kind;dialog.querySelector('[data-admin-panel="'+kind+'"]').append(nav);
  for(const [selector,difference] of [['[data-prev]',-100],['[data-next]',100]])nav.querySelector(selector).onclick=()=>action(async()=>{const key=kind==='codes'?codeTab():kind;offsets[key]=Math.max(0,offsets[key]+difference);await(kind==='codes'?loadCodes():loadUsers());status.textContent=''});
 }
 function pageInfo(kind,count){const nav=dialog.querySelector('[data-pagination="'+kind+'"]'),offset=offsets[kind==='codes'?codeTab():kind];nav.querySelector('span').textContent='第 '+(offset/100+1)+' 页';nav.querySelector('[data-prev]').disabled=offset===0;nav.querySelector('[data-next]').disabled=count<100}
 async function request(path,body){const response=await accountFetch('/api/admin/membership/'+path,{...(body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),cache:'no-store',signal:AbortSignal.timeout(20000)});const data=await response.json();if(!response.ok)throw Error(data.error||'操作未完成，请重试');return data}
 async function action(callback){if(busy)return;busy=true;dialog.querySelectorAll('button[type=submit]').forEach(button=>button.disabled=true);status.textContent='处理中…';try{await callback()}catch(error){status.textContent=error.name==='TimeoutError'?'请求暂未完成，请刷新列表确认结果。':error.message}finally{busy=false;dialog.querySelectorAll('button[type=submit]').forEach(button=>button.disabled=false)}}
 function option(value,label){const node=document.createElement('option');node.value=value;node.textContent=label;return node}
 function fillPlan(plan){const form=el('adminPlanForm');form.reset();form.elements.plan_id.value=plan?.id||'';if(!plan)return;for(const key of ['name','price_display','duration_days','max_concurrent','image_units','video_units'])form.elements[key].value=plan[key]??'';form.elements.active.checked=!!plan.active;form.querySelectorAll('[name=feature]').forEach(input=>input.checked=(plan.features||[]).includes(input.value));form.querySelectorAll('[name=backend]').forEach(input=>input.checked=(plan.backends||[]).includes(input.value))}
 async function loadPlans(){const data=await request('plans');plans=data.plans||[];const selected=el('adminPlanSelect').value;el('adminPlanSelect').replaceChildren(option('','新建套餐'),...plans.map(plan=>option(plan.id,plan.name+(plan.active?'':' · 已停用'))));el('adminPlanSelect').value=plans.some(plan=>plan.id===selected)?selected:'';el('adminCodePlan').replaceChildren(...plans.filter(plan=>plan.active).map(plan=>option(plan.id,plan.name)));if(!el('adminCodePlan').options.length)el('adminCodePlan').append(option('','请先启用一个套餐'))}
 function row(...values){const tr=document.createElement('tr');for(const value of values){const td=document.createElement('td');if(value instanceof Node)td.append(value);else td.textContent=String(value??'—');tr.append(td)}return tr}
 function rowButton(label,callback){const button=document.createElement('button');button.type='button';button.className='account-secondary';button.textContent=label;button.onclick=()=>action(async()=>{button.disabled=true;try{await callback()}finally{button.disabled=false}});return button}
 function showIssued(codes,label){if(!dialog.open)return;el('adminIssuedCodes').value=codes.filter(code=>typeof code==='string'&&code).join('\n');dialog.querySelector('label[for=adminIssuedCodes]').textContent=label;el('adminIssued').hidden=false}
 async function loadCodes(){const renewing=tab==='renewals',path=codePath(),label=codeName();el('adminCodeHelp').textContent=renewing?'一次性续费码在用户登录后兑换；原登录激活码、历史与收藏保留。':'每个登录激活码对应一个独立账号，首次使用时开通套餐，以后用同一个码继续登录。';el('adminCodeForm button[type=submit]').textContent='生成'+label;const data=await request(path+'?offset='+offsets[codeTab()]);const rows=(data.codes||[]).map(code=>{const used=renewing?code.redeemed_at:code.activated_at,userId=renewing?code.redeemed_by:code.user_id,state=code.revoked_at?'已作废':used?(renewing?'已兑换':'使用中')+' · 用户 '+String(userId||'').slice(0,8):'未使用',name=plans.find(plan=>plan.id===code.plan_id)?.name||'套餐';return row('…'+code.code_hint,name+(code.note?' · '+code.note:''),state,code.revoked_at||(renewing&&used)?'—':rowButton('作废',async()=>{const message=renewing?'作废后该续费码将无法兑换，确定继续？':'作废后此登录码和现有会话立即失效；账号内的套餐、历史与收藏保留。确定继续？';if(!confirm(message)){status.textContent='';return}await request(path+'/revoke',{code_id:code.id});await loadCodes();status.textContent=label+'已作废。'}))});el('adminCodesRows').replaceChildren(...(rows.length?rows:[row('暂无'+label,'','','')]));pageInfo('codes',rows.length)}
 async function loadUsers(){const data=await request('users?offset='+offsets.users);const rows=(data.users||[]).map(user=>{const controls=document.createElement('div');controls.className='admin-settle-actions';if(!user.is_admin){controls.append(rowButton(user.disabled?'恢复账号':'停用账号',async()=>{if(!confirm(user.disabled?'恢复此账号的使用权限？恢复后需要发放新的登录码。':'停用后该用户将无法继续使用，旧登录码与会话立即失效，确定停用？')){status.textContent='';return}await request('users/disable',{user_id:user.id,disabled:!user.disabled});await loadUsers();status.textContent=user.disabled?'账号已恢复，请更换登录码后交付用户。':'账号已停用，旧登录码已失效。'}));controls.append(rowButton('更换登录码',async()=>{if(!confirm('更换后，旧登录码和已登录会话立即失效。新码继续使用原账号的套餐、历史与收藏。确认更换？')){status.textContent='';return}const result=await request('users/rotate-code',{user_id:user.id,note:'管理员在用户管理中更换登录激活码'});showIssued([result.code?.code||result.code||result.access_code?.code],'新登录激活码 · 用户 '+String(user.id).slice(0,8));await loadUsers();status.textContent='登录激活码已更换，旧码已失效。请复制新码交给用户。'}))}else controls.textContent='—';return row((user.display_name||user.username||user.email||'JT 用户')+' · '+String(user.id).slice(0,8),(user.is_admin?'管理员 · ':'')+(user.disabled?'已停用':'正常')+(user.membership?.plan?.name?' · '+user.membership.plan.name+(user.membership.active?'':'（已到期）'):''),controls)});
  el('adminUsersRows').replaceChildren(...(rows.length?rows:[row('暂无用户','','')]));pageInfo('users',rows.length)}
 function selectSettlement(item,success){settlement={job_id:item.job_id,success};el('adminSettleTitle').textContent=success?'确认已产出，结算额度':'确认未产出，退回额度';el('adminSettleTarget').textContent='任务 '+item.job_id+' · '+(item.kind==='video'?'视频':'图片')+' '+item.units+' 单位';el('adminSettleNote').value='';el('adminSettleSubmit').textContent=success?'确认计费':'确认退回额度';el('adminSettleForm').hidden=false;el('adminSettleNote').focus()}
 async function loadReservations(){const data=await request('reservations');const stateLabels={queued:'排队中',running:'进行中',recovering:'恢复核对中',error:'未完成',cancelled:'已取消',done:'已完成'};const rows=(data.reservations||[]).map(item=>{
  const controls=document.createElement('div');controls.className='admin-settle-actions';
  if(item.can_settle===true&&!['queued','running','recovering','submitting'].includes(item.job_status)){
   for(const [label,success] of [['确认计费',true],['退回额度',false]]){const button=document.createElement('button');button.type='button';button.className='account-secondary';button.textContent=label;button.onclick=()=>{if(!busy)selectSettlement(item,success)};controls.append(button)}
  }else{const button=document.createElement('button');button.type='button';button.className='account-secondary';button.textContent='暂不可操作';button.disabled=true;controls.append(button)}
  const tr=row(String(item.job_id)+' / '+String(item.user_id).slice(0,8),(item.kind==='video'?'视频':'图片')+' · '+item.units+' 单位',(stateLabels[item.job_status]||'待核对')+(item.reason?' · '+item.reason:''),controls);tr.dataset.reservation=item.job_id;return tr;
 });el('adminReservationsRows').replaceChildren(...(rows.length?rows:[row('暂无待核对额度','','','')]))}
 async function loadTab(){await loadPlans();if(tab==='codes'||tab==='renewals')await loadCodes();if(tab==='users')await loadUsers();if(tab==='reservations')await loadReservations()}
 trigger.onclick=()=>{dialog.showModal();action(async()=>{await loadTab();status.textContent=''})};el('membershipAdminClose').onclick=()=>dialog.close();
 dialog.addEventListener('close',()=>{el('adminIssuedCodes').value='';el('adminIssued').hidden=true;el('adminSettleForm').hidden=true;settlement=null});
 window.addEventListener('jt:auth-expired',()=>{if(dialog.open)dialog.close()});
 dialog.querySelectorAll('[data-admin-tab]').forEach(button=>button.onclick=()=>{if(busy)return;tab=button.dataset.adminTab;dialog.querySelectorAll('[data-admin-tab]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));dialog.querySelectorAll('[data-admin-panel]').forEach(panel=>panel.hidden=panel.dataset.adminPanel!==(tab==='renewals'?'codes':tab));action(async()=>{await loadTab();status.textContent=''})});
 el('adminPlanSelect').onchange=()=>fillPlan(plans.find(plan=>plan.id===el('adminPlanSelect').value));
 el('adminPlanForm').onsubmit=event=>{event.preventDefault();action(async()=>{const form=event.currentTarget,data=new FormData(form),payload={name:data.get('name'),price_display:data.get('price_display'),duration_days:Number(data.get('duration_days')),max_concurrent:Number(data.get('max_concurrent')),image_units:Number(data.get('image_units')),video_units:Number(data.get('video_units')),features:data.getAll('feature'),backends:data.getAll('backend'),active:data.has('active')};if(data.get('plan_id'))payload.plan_id=data.get('plan_id');if(!payload.features.length||!payload.backends.length)throw Error('请至少选择一种功能和生成方式');const result=await request('plans',payload);await loadPlans();const plan=result.plan||result;el('adminPlanSelect').value=plan.id||'';fillPlan(plans.find(item=>item.id===plan.id));status.textContent='套餐已保存。'})};
 el('adminCodeForm').onsubmit=event=>{event.preventDefault();const data=new FormData(event.currentTarget);action(async()=>{if(!data.get('plan_id'))throw Error('请先创建并启用套餐');const result=await request(codePath(),{plan_id:data.get('plan_id'),count:Number(data.get('count')),note:data.get('note')});showIssued((result.codes||[]).map(code=>code.code),'本次生成的'+codeName());offsets[codeTab()]=0;await loadCodes();status.textContent=codeName()+'已生成，请复制保存。'})};
 el('adminCopyCodes').onclick=async()=>{try{await navigator.clipboard.writeText(el('adminIssuedCodes').value);status.textContent='已复制。'}catch{el('adminIssuedCodes').focus();el('adminIssuedCodes').select();status.textContent='已选中，请按 Ctrl+C 复制。'}};
 el('adminReservationsRefresh').onclick=()=>action(async()=>{await loadReservations();status.textContent='待核对列表已更新。'});
 el('adminSettleCancel').onclick=()=>{el('adminSettleForm').hidden=true;settlement=null};
 el('adminSettleForm').onsubmit=event=>{event.preventDefault();if(!settlement||busy)return;const note=el('adminSettleNote').value.trim();if(note.length<10){status.textContent='请填写至少 10 字的核对依据。';el('adminSettleNote').focus();return}const payload={...settlement,note};const message=payload.success?'已核实此任务确实产出结果，确认结算所占额度？':'已核实此任务没有产出结果，确认退回所占额度？';if(!confirm(message))return;action(async()=>{await request('reservations/settle',payload);settlement=null;el('adminSettleForm').hidden=true;await loadReservations();status.textContent=payload.success?'额度已结算。':'额度已退回。'})};
 return {dialog,trigger};
}
